-- 394: Original BrillaPrep NSMQ subj_nsmq_chemistry problem_of_day beta questions (batch 001).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_394_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_394_guard;
INSERT INTO _migration_394_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_pod_b001_001' AND NOT (q.topic_id IS 'topic_nsmq_chem_stoichiometry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the number of moles in 20.0 g of sodium hydroxide, NaOH. (Na = 23, O = 16, H = 1)' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '0.5 mol' AND q.explanation IS 'Molar mass of NaOH = 23 + 16 + 1 = 40 g/mol. Moles n = mass/molar mass = 20.0/40 = 0.5 mol. This is the standard n = m/M relationship used throughout quantitative chemistry.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_pod_b001_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_394_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_pod_b001_002' AND NOT (q.topic_id IS 'topic_nsmq_chem_stoichiometry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What volume does 0.25 mol of an ideal gas occupy at s.t.p.? (Molar volume = 22.4 dm³/mol)' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '5.6 dm³' AND q.explanation IS 'Volume = moles × molar volume = 0.25 × 22.4 = 5.6 dm³. At standard temperature and pressure one mole of any ideal gas occupies 22.4 dm³, so a quarter mole occupies a quarter of that volume.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_pod_b001_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_394_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_pod_b001_003' AND NOT (q.topic_id IS 'topic_nsmq_chem_electrochemistry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A current of 2.0 A is passed through a solution of AgNO₃ for 965 s. Calculate the mass of silver deposited. (F = 96 500 C/mol, Ag = 108 g/mol)' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '2.16 g' AND q.explanation IS 'Charge Q = It = 2.0 × 965 = 1930 C. Moles of electrons = Q/F = 1930/96 500 = 0.02 mol. The half-equation Ag⁺ + e⁻ → Ag shows one electron deposits one silver atom, so n(Ag) = 0.02 mol. Mass = 0.02 × 108 = 2.16 g.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_pod_b001_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_394_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_pod_b001_004' AND NOT (q.topic_id IS 'topic_nsmq_chem_equilibrium' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g) at equilibrium, [N₂] = 0.10 M, [H₂] = 0.10 M and [NH₃] = 0.20 M. Calculate the value of Kc.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '400 mol⁻² dm⁶' AND q.explanation IS 'Kc = [NH₃]²/([N₂][H₂]³) using the stoichiometric coefficients as powers. Substituting: Kc = (0.20)²/(0.10 × (0.10)³) = 0.04/0.0001 = 400. The units are (mol dm⁻³)²/(mol dm⁻³)⁴ = mol⁻² dm⁶.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_pod_b001_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_chem_pod_b001_001', 'topic_nsmq_chem_stoichiometry', 'subj_nsmq_chemistry', 'exam_nsmq', NULL, NULL, 'Calculate the number of moles in 20.0 g of sodium hydroxide, NaOH. (Na = 23, O = 16, H = 1)', 'problem', 'problem_of_day', NULL, '0.5 mol', 'Molar mass of NaOH = 23 + 16 + 1 = 40 g/mol. Moles n = mass/molar mass = 20.0/40 = 0.5 mol. This is the standard n = m/M relationship used throughout quantitative chemistry.', 'medium', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_chem_pod_b001_002', 'topic_nsmq_chem_stoichiometry', 'subj_nsmq_chemistry', 'exam_nsmq', NULL, NULL, 'What volume does 0.25 mol of an ideal gas occupy at s.t.p.? (Molar volume = 22.4 dm³/mol)', 'problem', 'problem_of_day', NULL, '5.6 dm³', 'Volume = moles × molar volume = 0.25 × 22.4 = 5.6 dm³. At standard temperature and pressure one mole of any ideal gas occupies 22.4 dm³, so a quarter mole occupies a quarter of that volume.', 'medium', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_chem_pod_b001_003', 'topic_nsmq_chem_electrochemistry', 'subj_nsmq_chemistry', 'exam_nsmq', NULL, NULL, 'A current of 2.0 A is passed through a solution of AgNO₃ for 965 s. Calculate the mass of silver deposited. (F = 96 500 C/mol, Ag = 108 g/mol)', 'problem', 'problem_of_day', NULL, '2.16 g', 'Charge Q = It = 2.0 × 965 = 1930 C. Moles of electrons = Q/F = 1930/96 500 = 0.02 mol. The half-equation Ag⁺ + e⁻ → Ag shows one electron deposits one silver atom, so n(Ag) = 0.02 mol. Mass = 0.02 × 108 = 2.16 g.', 'hard', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_chem_pod_b001_004', 'topic_nsmq_chem_equilibrium', 'subj_nsmq_chemistry', 'exam_nsmq', NULL, NULL, 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g) at equilibrium, [N₂] = 0.10 M, [H₂] = 0.10 M and [NH₃] = 0.20 M. Calculate the value of Kc.', 'problem', 'problem_of_day', NULL, '400 mol⁻² dm⁶', 'Kc = [NH₃]²/([N₂][H₂]³) using the stoichiometric coefficients as powers. Substituting: Kc = (0.20)²/(0.10 × (0.10)³) = 0.04/0.0001 = 400. The units are (mol dm⁻³)²/(mol dm⁻³)⁴ = mol⁻² dm⁶.', 'hard', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_chem_pod_b001_001', 'q_nsmq_chem_pod_b001_002', 'q_nsmq_chem_pod_b001_003', 'q_nsmq_chem_pod_b001_004');
